use crate::{mswm01 as m,catalog,model::*,unit_support::*};
use crate::jc029_tests::pass_top;
fn setup()->Game{let mut g=game();g.players[0].society_zone.card=Some(g.make_card(m::ID,0));fund(&mut g,0,"BQ064",8);deck_cards(&mut g,0,&["JC125";8]);g}
fn action(g:&Game,key:&str,ids:Option<Vec<String>>)->Action{Action{card_id:Some(g.players[0].society_zone.card.as_ref().unwrap().id.clone()),ability_id:Some(key.into()),cost_selected:ids,..Action::new("activate")}}
fn grant(g:&mut Game){let a=action(g,m::GRANT,None);act(g,0,a);pass_top(g);restore(g);}
fn spectral(g:&Game,c:&Card)->bool{g.current_subtypes(c).iter().any(|s|s=="阴魂")}
#[test]
fn mswm01_closed_construction_matches_original(){let s=crate::society::definition(m::ID).unwrap();assert!(!s.card.supported);assert_eq!(s.card.color,"蓝");assert_eq!(s.starting_hand,6);assert_eq!(s.subtitle,"不死阴魂");for c in &catalog::catalog().cards{let expected=matches!(c.color.as_str(),"蓝"|"黄"|"中立")||(c.kind=="character"&&c.subtypes.iter().any(|s|matches!(s.as_str(),"吸血鬼"|"阴魂")));assert_eq!(crate::society::validate_construction(s,&[catalog::DeckEntry{card_id:c.id.clone(),count:1}],&catalog::catalog().cards).is_ok(),expected,"{}",c.id);}}
#[test]
fn mswm01_whole_game_owner_grant_tracks_zones_and_not_control(){let mut g=setup();let own=field(&mut g,"JC029",0);let other=field(&mut g,"JC029",2);grant(&mut g);assert_eq!(g.resources(0),4);assert!(spectral(&g,g.board(&own).unwrap().1));assert!(!spectral(&g,g.board(&other).unwrap().1));g.board_mut(&own).unwrap().controller=2;g.board_mut(&other).unwrap().controller=0;assert!(spectral(&g,g.board(&own).unwrap().1));assert!(!spectral(&g,g.board(&other).unwrap().1));g.players[0].society_zone.card=None;assert!(spectral(&g,g.board(&own).unwrap().1));g.remove_dead(&own,RemovalCause::Destroy);assert!(spectral(&g,g.players[0].graveyard.last().unwrap()));let c=g.make_card("JC029",0);assert!(spectral(&g,&c));g.players[0].hand.push(c);let c=g.make_card("JC029",0);g.players[0].deck.push(c);restore(&mut g);}
#[test]
fn mswm01_draw_condition_at_resolution_and_cost_stays_paid(){for (before,after) in [(0,0),(1,0),(0,1),(1,1)]{let mut g=setup();let def=catalog::catalog().cards.iter().find(|c|c.kind=="character"&&c.subtypes.iter().any(|s|s=="阴魂")).unwrap().id.clone();let id=field(&mut g,&def,0);g.players[0].society_zone.exposure=before;let a=action(&g,m::DRAW,Some(vec![id.clone()]));assert!(g.legal_actions(0).iter().any(|x|x.action==a));act(&mut g,0,a);assert!(g.board(&id).unwrap().1.exhausted);g.players[0].society_zone.exposure=after;g.remove_dead(&id,RemovalCause::Destroy);restore(&mut g);pass_top(&mut g);assert_eq!(g.players[0].hand.len(),usize::from(after==0));assert_eq!(g.resources(0),8);restore(&mut g);}}
#[test]
fn mswm01_invalid_payment_atomic_and_restore_receipts(){let mut g=setup();let id=field(&mut g,"JC029",0);let a=action(&g,m::DRAW,Some(vec![id.clone()]));reject(&mut g,0,a);grant(&mut g);g.players[0].society_zone.card.as_mut().unwrap().exhausted=false;for ids in [vec![],vec![id.clone(),id.clone()]]{let a=action(&g,m::DRAW,Some(ids));reject(&mut g,0,a);}let a=action(&g,m::DRAW,Some(vec![id]));act(&mut g,0,a);for case in 0..4{let mut bad=g.clone();let f=bad.stack.last_mut().unwrap().frame.as_mut().unwrap();match case{0=>{f.already_paid.pop();},1=>f.source.card.definition="MSJC09".into(),2=>f.steps[0].op=crate::rules::Op::MSWM01{grant:true},_=>f.actor=2}assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());let mut room=crate::jc029_tests::envelope(&g);room.game=bad;assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&room).unwrap()).is_err());}pass_top(&mut g);assert_eq!(g.players[0].hand.len(),1);restore(&mut g);}
fn duplicate(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.outcome,"rejected");assert_eq!(d.state,s["expected"]["state"]);assert!(!d.changed&&d.journal.is_empty());s["duplicate"]=serde_json::to_value(d).unwrap();}v}
fn drain(t:&mut crate::abi112_review_play_tests::Trace){for _ in 0..100{if let Some(p)=t.room.game.pending.clone(){t.choose(p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect());}else if t.room.game.stack.is_empty()&&t.room.game.effects.is_empty()&&t.room.game.mystic_contest.is_none(){return;}else{t.pass();}}panic!("曼纽等待未收束");}
fn prepared()->serde_json::Value{use crate::abi112_review_play_tests::Trace;let mut g=setup();let id=field(&mut g,"JC029",0);let mut t=Trace::new_preserving_rng(g,"mswm01-prepared-grant-draw".into(),801);let a=action(&t.room.game,m::GRANT,None);t.action(0,a);drain(&mut t);for _ in 0..150{let g=&t.room.game;let a=action(g,m::DRAW,Some(vec![id.clone()]));if g.legal_actions(0).iter().any(|l|l.action==a){let n=g.players[0].hand.len();t.action(0,a);drain(&mut t);assert_eq!(t.room.game.players[0].hand.len(),n+1);return duplicate(t.value());}if let Some(p)=g.pending.clone(){t.choose(p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect());}else{t.pass();}}panic!("未到抓牌入口");}
fn natural()->serde_json::Value{use crate::{deck,abi112_review_play_tests::Trace};let vampire="JC029".to_string();
 fn construct(seed:u64,vampire:&str)->Game{let mut d=deck::preset("watchers").unwrap();d.id="mswm01-natural".into();d.society_id=Some(m::ID.into());d.core_card_id=None;d.cards=vec![catalog::DeckEntry{card_id:vampire.into(),count:3},catalog::DeckEntry{card_id:"JC125".into(),count:47}];assert!(deck::validate(d.clone()).is_err());let mut societies=catalog::catalog().societies.clone();societies.iter_mut().find(|s|s.card.id==m::ID).unwrap().card.supported=true;let d=deck::validate_with_registry(d,&catalog::catalog().cards,&societies).unwrap();let mut other=deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("mswm01".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d,other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();g}
 let (seed,g)=(1..4097).find_map(|seed|{let g=construct(seed,&vampire);(g.players[0].hand.iter().filter(|c|c.definition==vampire).count()==3).then_some((seed,g))}).unwrap();let deck=g.players[0].deck_snapshot.clone().unwrap();let mut t=Trace::new_preserving_rng(g,"mswm01-natural-fifty-cards-grant-draw".into(),802);let mut done=false;let mut before=0;
 for _ in 0..1200{if let Some(p)=t.room.game.pending.clone(){let mut opts=p.choice.options.iter().collect::<Vec<_>>();opts.sort_by_key(|o|t.room.game.players[p.seat].hand.iter().any(|c|c.id==o.id&&c.definition==vampire));t.choose(opts.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect());continue;}if done&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}if !t.room.game.stack.is_empty(){t.pass();continue;}let g=&t.room.game;let legal=g.legal_actions(0);let blue=g.players[0].assets.iter().filter(|c|catalog::card(&c.definition).color=="蓝").count();let a=if blue<2{legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition==vampire)))}else if g.players[0].assets.len()<4{legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition=="JC125")))}else if !g.regions.iter().flat_map(|r|&r.cards).any(|c|c.controller==0&&c.definition==vampire){legal.iter().find(|a|a.action.kind=="deploy"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition==vampire)))}else{legal.iter().find(|a|a.action.ability_id.as_deref()==Some(if g.mswm01_grants.is_empty(){m::GRANT}else{m::DRAW}))};if let Some(a)=a{if a.action.ability_id.as_deref()==Some(m::DRAW){done=true;before=g.players[0].hand.len();}t.action(0,a.action.clone());}else{t.pass();}}
 assert!(done,"natural chain failed turn {}",t.room.game.turn);assert_eq!(t.room.game.players[0].hand.len(),before+1);let mut v=t.value();v["construction"]=serde_json::json!({"deck":deck,"seed":seed,"ordinaryCards":50,"privateRegistryOnly":true,"noLayoutOrResourceMutation":true});duplicate(v)
}
#[test]
fn mswm01_native_natural_and_prepared_export(){let mut cases=vec![natural(),prepared()];cases.extend(contests());let mut binding=crate::bq052_tests::source_bindings();use sha2::{Digest,Sha256};for(n,bytes)in[("rust-game/src/mswm01.rs",include_bytes!("mswm01.rs").as_slice()),("rust-game/src/mswm01_tests.rs",include_bytes!("mswm01_tests.rs").as_slice()),("rust-game/src/control.rs",include_bytes!("control.rs").as_slice()),("rust-game/src/society.rs",include_bytes!("society.rs").as_slice()),("rust-game/src/mystic_contest.rs",include_bytes!("mystic_contest.rs").as_slice())]{binding["files"][n]=serde_json::json!(format!("{:x}",Sha256::digest(bytes)));}if let Ok(p)=std::env::var("MSWM01_NATIVE_OUT"){std::fs::write(p,serde_json::to_vec(&serde_json::json!({"catalog":catalog::catalog(),"sourceBindings":binding,"cases":cases})).unwrap()).unwrap();}}
fn contests()->Vec<serde_json::Value>{let mut cases=vec![];for paid in [false,true]{let mut g=setup();if paid{grant(&mut g);}g.begin_window(Window::Action(0));let spell=held(&mut g,"BQ062",0);for seat in 0..4{held(&mut g,if seat==0{"JC029"}else{"JC125"},seat);}let a=Action{card_id:Some(spell),ability_id:Some("bq062-command".into()),option:Some("contest".into()),..Action::new("play")};let legal=g.legal_actions(0).into_iter().find(|l|l.action.card_id==a.card_id&&l.action.option.as_deref()==Some("contest")).unwrap().action;let mut t=crate::abi112_review_play_tests::Trace::new_preserving_rng(g,format!("mswm01-contest-{paid}"),803+usize::from(paid));t.action(0,legal);drain(&mut t);let g=&mut t.room.game;assert_eq!(g.mystic_history.len(),1);let shown=&g.mystic_history[0].shown[0];assert_eq!(shown.value,catalog::card("JC029").cost+u32::from(paid));assert_eq!(shown.mswm01.is_some(),paid);g.players[0].society_zone.card=None;restore(g);if paid{let mut bad=g.clone();bad.mystic_history[0].shown[0].mswm01.as_mut().unwrap().grant.as_mut().unwrap().already_paid.clear();assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());}cases.push(duplicate(t.value()));}cases}
#[test]
fn mswm01_contest_bonus_freezes_reveal_and_grant_does_not_rewrite_history(){assert_eq!(contests().len(),2);}
#[test]
fn mswm01_conversion_hide_owner_and_repeated_grant_are_not_stacked(){
 let mut g=setup();let human=field(&mut g,"JC125",0);grant(&mut g);assert!(!spectral(&g,g.board(&human).unwrap().1));
 g.add_control(&human,2,ControlLifetime::TurnEnd{turn:g.turn},SubtypeChange::HumanToVampire);assert!(spectral(&g,g.board(&human).unwrap().1));restore(&mut g);
 let foreign=field(&mut g,"JC125",2);g.add_control(&foreign,0,ControlLifetime::TurnEnd{turn:g.turn},SubtypeChange::HumanToVampire);assert!(!spectral(&g,g.board(&foreign).unwrap().1));
 let own=field(&mut g,"JC029",0);assert!(g.hide_in_place(&own));let c=g.regions.iter().flat_map(|r|&r.cards).find(|c|c.definition=="JC029").unwrap();assert!(g.current_subtypes(c).is_empty());
 g.players[0].society_zone.card.as_mut().unwrap().exhausted=false;g.begin_window(Window::Action(0));grant(&mut g);assert_eq!(g.resources(0),0);assert_eq!(g.mswm01_grants.len(),1);restore(&mut g);
 let mage=catalog::catalog().cards.iter().find(|c|c.kind=="character"&&c.subtypes.iter().any(|s|s=="法师")).unwrap().id.clone();let c=g.make_card(&mage,0);assert!(spectral(&g,&c));assert_eq!(g.current_subtypes(&c).iter().filter(|s|s.as_str()=="阴魂").count(),1);
 let mut bad=g.clone();bad.mswm01_grants.push(bad.mswm01_grants[0].clone());assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());
 let d=crate::deck::preset("watchers").unwrap();g.start_validated_decks(vec![d.clone();4]).unwrap();assert!(g.mswm01_grants.is_empty());
}
#[test]
fn mswm01_printed_specter_bonus_and_later_grant_preserve_old_witness(){
 use crate::mystic_contest::MysticShown;
 let mut g=setup();let def=catalog::catalog().cards.iter().find(|c|c.subtypes.iter().any(|s|s=="阴魂")).unwrap().id.clone();let c=g.make_card(&def,0);
 let mut shown=MysticShown{mswm01:g.mswm01_shown(0,&c),core_support:None,anchor_witness:None,politician_asset:None,seat:0,card:c,manor:None,vampire_observers:vec![],destroyed_regions:vec![],destruction_markers:0,value:0};assert!(shown.mswm01.as_ref().unwrap().grant.is_none());assert_eq!(g.mswm01_shown_bonus(&shown).unwrap(),1);
 g.players[0].society_zone.card.as_mut().unwrap().face_down=true;assert!(g.mswm01_shown(0,&shown.card).is_none());assert_eq!(g.mswm01_shown_bonus(&shown).unwrap(),1);
 g.players[0].society_zone.card.as_mut().unwrap().face_down=false;shown.card=g.make_card("JC029",0);shown.mswm01=None;assert_eq!(g.mswm01_shown_bonus(&shown).unwrap(),0);grant(&mut g);assert_eq!(g.mswm01_shown_bonus(&shown).unwrap(),0);assert!(g.mswm01_shown(0,&shown.card).unwrap().grant.is_some());
}
#[test]
fn mswm01_closed_program_and_empty_deck_draw_boundaries(){let original=m::definition();for n in 0..4{let mut d=original.clone();match n{0=>d.abilities[0].costs.clear(),1=>d.abilities[1].timing=crate::rules::Timing::Fast,2=>d.abilities[1].ops.clear(),_=>{d.abilities.pop();}}assert!(m::validate_definition(m::ID,&d).is_err());}assert!(m::validate_definition("MSJC09",&original).is_err());for n in [0,1]{let mut g=setup();let def=catalog::catalog().cards.iter().find(|c|c.kind=="character"&&c.subtypes.iter().any(|s|s=="阴魂")).unwrap().id.clone();let id=field(&mut g,&def,0);deck_cards(&mut g,0,&vec!["JC125";n]);let a=action(&g,m::DRAW,Some(vec![id]));act(&mut g,0,a);pass_top(&mut g);assert_eq!(g.players[0].eliminated,n==0);assert_eq!(g.players[0].hand.len(),n);restore(&mut g);}}

#[test]
fn mswm01_whole_game_grant_respects_asset_and_sealed_blanking(){let mut g=setup();grant(&mut g);let asset=g.make_card("JC029",0);g.players[0].assets.push(asset.clone());let sealed=g.make_card("JC029",0);g.sealed_cards.push(SealedCard{card:sealed.clone(),host_id:"society:p0".into()});assert!(!spectral(&g,&asset));assert!(!spectral(&g,&sealed));let asset=g.players[0].assets.pop().unwrap();g.players[0].hand.push(asset.clone());assert!(spectral(&g,&asset));let sealed=g.sealed_cards.pop().unwrap().card;g.players[0].graveyard.push(sealed.clone());assert!(spectral(&g,&sealed));restore(&mut g);}
